def zone_links(exclude=None):
    return "".join(f'<a class="chip" href="{z["f"]}">{z["court"]}</a>' for z in ZONES if z["f"]!=exclude)

for z in ZONES:
    body = page_hero(f'<a href="courtier-bretagne.html">Nos secteurs</a> / {z["court"]}', f'Courtier · {z["court"]}', z["h1"], z["lead"]) + f'''
<section class="section"><div class="wrap split">
<div class="prose"><span class="eyebrow">{z["court"]}</span><h2 style="color:var(--text)">{z["intro_h"]}</h2>{z["intro"]}</div>
<div class="panel">{ticks(z["projets"])}</div></div></section>
<section class="section white"><div class="wrap">
<div class="section-head"><span class="eyebrow">Nos expertises</span><h2>Tous vos financements, à {z["nom"]}</h2></div>
<div class="cards">{"".join(f'<a class="card" href="{f}"><div class="ico">{I[i]}</div><span class="tag">{tag}</span><h3>{t}</h3><p>{d}</p><span class="more">Découvrir {I["arrow"]}</span></a>' for f,i,t,tag,d,k in EXPERTISES)}</div></div></section>
<section class="section"><div class="wrap">
<div class="section-head"><span class="eyebrow">Simulateur</span><h2>Combien pouvez-vous emprunter ?</h2></div>{sim_capacite("z"+z["f"][8:12])}</div></section>
<section class="section white"><div class="wrap split">
<div class="section-head"><span class="eyebrow">Avis clients</span><h2>5,0 sur 204 avis Google</h2><p class="lead">Nos clients du pays de Lorient, du Morbihan et d'ailleurs en parlent mieux que nous.</p>
<div><a class="btn btn-outline" href="https://www.google.com/maps/search/?api=1&query=KAIRN+8+mail+Jeanne+Villepreux+Lorient" rel="noopener">Lire les avis {I["arrow"]}</a></div></div>
<div class="panel"><h3 style="font-size:1rem;letter-spacing:.06em">Communes accompagnées</h3><p style="margin-top:10px;color:var(--muted)">{z["communes"]}</p>
<h3 style="font-size:1rem;letter-spacing:.06em;margin-top:22px">Nos autres secteurs</h3><div class="chips" style="margin-top:10px">{zone_links(z["f"])}</div></div>
</div></section>
<section class="section"><div class="wrap split"><div class="section-head"><span class="eyebrow">Questions fréquentes</span><h2>Vos questions</h2></div>{faq(z["faqs"])}</div></section>
{cta_band(f"Un projet à {z['nom']} ?")}'''
    page(z["f"], z["seo"][0], z["seo"][1], body, local=z)
